//! Rendering as a function: total on the admitted space, and distinguishing.
//!
//! Two properties, and the second is the one with teeth. Totality says the renderer
//! cannot fail or panic on anything strict decoding accepts — that is what lets the
//! renderer have no error type at all. Distinguishability says two different permits
//! never produce the same signed text: if they could, one signature would authorize
//! both, and a user consenting to one permit would have consented to the other.
//!
//! The sample is generated by a named deterministic generator, not a random one, so a
//! failure reproduces on the next run and in the other implementations.
//!
//! One asymmetry is deliberate and shows up here: the text commits to the transport
//! key through a 32-byte fingerprint, so distinguishability with respect to that field
//! is collision resistance of the digest rather than a structural property. Every
//! other field appears in the text in full.

mod common;

use common::*;
use std::collections::HashMap;
use zama_solana_permit::{
    render_canonical_text, KmsRouting, PermitFields, PermitWireFields, MAX_ALLOWED_SCOPES,
    MAX_DURATION_SECONDS, MAX_START_TIMESTAMP,
};

/// Size of the deterministic sample. Large enough to cover every scope count and
/// both ends of every bound many times over.
const SAMPLE: u64 = 1024;

// ---------------------------------------------------------------------------
// Totality
// ---------------------------------------------------------------------------

/// Whatever strict decoding accepts, the renderer renders. There is no input the
/// renderer has to refuse, which is why it returns a text rather than a result.
#[test]
fn rendering_is_total_over_everything_decoding_accepts() {
    for seed in 0..SAMPLE {
        let fields = decoded(&pseudo_valid_wire(seed));
        let text = render_canonical_text(&fields);
        assert!(!text.is_empty(), "seed {seed} rendered nothing");
    }
}

/// The extreme corners specifically, since a generator can miss the simultaneous
/// extremes: both timestamp ends, both duration ends, both list ends, and the
/// integer extremes together.
#[test]
fn rendering_is_total_at_every_corner() {
    for start_timestamp in [0, MAX_START_TIMESTAMP] {
        for duration_seconds in [1, MAX_DURATION_SECONDS] {
            for chain_id in [0, u64::MAX] {
                for scope_count in [0usize, 1, MAX_ALLOWED_SCOPES] {
                    let wire = PermitWireFields {
                        start_timestamp,
                        duration_seconds,
                        chain_id,
                        ..wire_with_scope_count(scope_count)
                    };
                    let text = render_canonical_text(&decoded(&wire));
                    assert!(
                        !text.is_empty(),
                        "corner ({start_timestamp}, {duration_seconds}, {chain_id}, {scope_count}) rendered nothing"
                    );
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Distinguishability
// ---------------------------------------------------------------------------

#[test]
fn distinct_permits_never_share_a_canonical_text() {
    let mut seen: HashMap<String, PermitWireFields> = HashMap::new();

    for seed in 0..SAMPLE {
        let wire = pseudo_valid_wire(seed);
        let text = render_canonical_text(&decoded(&wire));

        if let Some(previous) = seen.insert(text.clone(), wire.clone()) {
            assert_eq!(
                previous, wire,
                "two different permits rendered the same text:\n{text}"
            );
        }
    }
}

/// Changing any one signed field changes the text.
///
/// This is the practical form of injectivity, and it is also the test that catches a
/// field being left out of the template entirely: a renderer that forgot the chain id
/// would still pass every golden built from a single fixture, but not this.
#[test]
fn changing_any_single_field_changes_the_text() {
    let baseline_wire = reference_wire();
    let baseline = render_canonical_text(&decoded(&baseline_wire));

    for (what, mutated) in single_field_mutations(&baseline_wire) {
        let rendered = render_canonical_text(&decoded(&mutated));
        assert_ne!(
            rendered, baseline,
            "changing {what} left the canonical text unchanged — the field is not committed to"
        );
    }
}

/// The same, from many starting points rather than one: a field could be committed to
/// for the reference permit and dropped for, say, permissive permits.
#[test]
fn changing_any_single_field_changes_the_text_from_many_baselines() {
    for seed in 0..64u64 {
        let baseline_wire = pseudo_valid_wire(seed);
        let baseline = render_canonical_text(&decoded(&baseline_wire));

        for (what, mutated) in single_field_mutations(&baseline_wire) {
            let rendered = render_canonical_text(&decoded(&mutated));
            assert_ne!(
                rendered, baseline,
                "seed {seed}: changing {what} left the canonical text unchanged"
            );
        }
    }
}

/// Every byte of the signed KMS routing field is committed to: flipping any one bit
/// of the context or the epoch changes the text.
///
/// The routing field is parsed before being rendered, so this is where a lossy parse
/// would show up — two routing byte strings rendering identically is exactly the hole
/// that would let one signature serve two KMS routings.
#[test]
fn every_byte_of_the_kms_routing_field_is_committed_to() {
    let baseline_wire = reference_wire();
    let baseline = render_canonical_text(&decoded(&baseline_wire));

    // Byte 0 is the version, which strict decoding pins to the single known value; the
    // remaining 64 bytes are the context and the epoch.
    for index in 1..baseline_wire.extra_data.len() {
        for bit in [0u8, 3, 7] {
            let mut mutated = baseline_wire.clone();
            mutated.extra_data[index] ^= 1 << bit;

            let rendered = render_canonical_text(&decoded(&mutated));
            assert_ne!(
                rendered, baseline,
                "flipping bit {bit} of routing byte {index} left the text unchanged"
            );
        }
    }
}

/// Distinct routing byte strings render distinct texts, pairwise across a sample —
/// not merely different from one baseline.
#[test]
fn distinct_kms_routings_render_pairwise_distinct_texts() {
    let mut seen: HashMap<String, Vec<u8>> = HashMap::new();
    let mut state = 0x00C0_FFEE_u64;

    for _ in 0..256 {
        let wire = PermitWireFields {
            extra_data: extra_data(pseudo_identity(&mut state), pseudo_identity(&mut state)),
            ..reference_wire()
        };
        let text = render_canonical_text(&decoded(&wire));

        if let Some(previous) = seen.insert(text.clone(), wire.extra_data.clone()) {
            assert_eq!(
                previous, wire.extra_data,
                "two routing byte strings rendered the same text"
            );
        }
    }
}

/// A build-time canary, not a runtime assertion.
///
/// The distinguishability rule binds future versions of the routing field too: a new
/// version must never render like an existing one. This match has no catch-all arm,
/// so adding a variant to the routing type stops the suite from compiling — at which
/// point whoever adds it has to state, here, how the new version's text is told apart
/// from this one's.
#[test]
fn routing_versions_are_enumerated_so_a_new_one_cannot_slip_through() {
    let (context, epoch) = kms_routing(&reference_fields());
    let routing = KmsRouting::ContextAndEpoch {
        kms_context_id: context,
        kms_epoch_id: epoch,
    };

    match routing {
        KmsRouting::ContextAndEpoch { .. } => {
            // The only known version. Its text is the two KMS lines; a second version
            // must render something no reader could confuse with them.
        }
    }
}

/// The text is a function of the fields alone: nothing ambient (time, environment,
/// iteration order, allocation addresses) leaks into it.
#[test]
fn rendering_depends_on_nothing_but_the_fields() {
    for seed in 0..64u64 {
        let wire = pseudo_valid_wire(seed);
        let first = render_canonical_text(&decoded(&wire));

        // A freshly decoded copy, and the same value rendered repeatedly.
        let reference = PermitFields::decode(&wire).expect("well formed");
        assert_eq!(render_canonical_text(&reference), first);
        assert_eq!(render_canonical_text(&reference), first);

        // A clone of the typed value, in case rendering ever consults an identity
        // rather than the contents.
        assert_eq!(render_canonical_text(&reference.clone()), first);
    }
}

// ---------------------------------------------------------------------------
// Mutations
// ---------------------------------------------------------------------------

/// One minimal change per signed field, each yielding a still-valid permit. The
/// transport key is included: it reaches the text only through its fingerprint, so
/// this is what checks that the fingerprint is actually recomputed rather than
/// rendered from something cached.
fn single_field_mutations(base: &PermitWireFields) -> Vec<(&'static str, PermitWireFields)> {
    let mut out = Vec::new();

    let mut user = base.clone();
    user.user_pubkey[31] ^= 1;
    out.push(("user pubkey", user));

    let mut program = base.clone();
    program.verifying_program_id[0] ^= 1;
    out.push(("verifying program id", program));

    out.push((
        "chain id",
        PermitWireFields {
            chain_id: base.chain_id ^ 1,
            ..base.clone()
        },
    ));

    out.push((
        "transport key",
        PermitWireFields {
            transport_key: transport_key_bytes(b"a different transport key"),
            ..base.clone()
        },
    ));

    out.push((
        "start timestamp",
        PermitWireFields {
            start_timestamp: if base.start_timestamp == MAX_START_TIMESTAMP {
                base.start_timestamp - 1
            } else {
                base.start_timestamp + 1
            },
            ..base.clone()
        },
    ));

    out.push((
        "duration",
        PermitWireFields {
            duration_seconds: if base.duration_seconds == MAX_DURATION_SECONDS {
                base.duration_seconds - 1
            } else {
                base.duration_seconds + 1
            },
            ..base.clone()
        },
    ));

    let mut context = base.clone();
    context.extra_data[1] ^= 1;
    out.push(("kms context id", context));

    let mut epoch = base.clone();
    epoch.extra_data[33] ^= 1;
    out.push(("kms epoch id", epoch));

    // The scope list: replace its last entry with a larger one, keeping the list
    // ascending, or add an entry to a permissive permit (a permissive permit and a
    // scoped one must not render alike either).
    let mut scopes = base.clone();
    match scopes.allowed_scopes.last_mut() {
        Some(last) => {
            // Raise the entry without disturbing the order: the fixture scopes leave room
            // in their final byte.
            let end = last.len() - 1;
            last[end] = last[end].wrapping_add(1);
        }
        None => {
            scopes.allowed_scopes = vec![scope_entry(
                bytes32(APP_PROGRAM_ID_HEX),
                bytes32(SCOPE_43_HEX),
            )];
        }
    }
    out.push(("scopes", scopes));

    out
}

/// The mutation set really does cover all eight signed fields. Otherwise the tests
/// above could be silently checking seven.
#[test]
fn the_mutation_set_covers_every_signed_field() {
    let names: Vec<&str> = single_field_mutations(&reference_wire())
        .into_iter()
        .map(|(name, _)| name)
        .collect();

    for expected in [
        "user pubkey",
        "transport key",
        "scopes",
        "start timestamp",
        "duration",
        "verifying program id",
        "chain id",
        "kms context id",
        "kms epoch id",
    ] {
        assert!(names.contains(&expected), "no mutation for {expected}");
    }
    // Eight signed fields, with the routing field contributing two.
    assert_eq!(names.len(), 9);
}

/// A mutation that gets rejected by decoding would make the test above vacuous.
#[test]
fn every_mutation_is_still_well_formed() {
    for seed in 0..64u64 {
        let base = pseudo_valid_wire(seed);
        for (what, mutated) in single_field_mutations(&base) {
            assert!(
                PermitFields::decode(&mutated).is_ok(),
                "seed {seed}: the {what} mutation produced a permit decoding rejects"
            );
        }
    }
}
